tokio::task_local! {
    static REQUEST_CTX: RequestContext;
}

pub async fn with_request_ctx<F: Future>(ctx: RequestContext, f: F) -> F::Output {
    REQUEST_CTX.scope(ctx, f).await      // bounded to this scope
}

pub fn current() -> RequestContext {
    REQUEST_CTX.with(|c| c.clone())      // panics outside the scope
}
